final class OrderFulfillmentService
{
    private const QR_CHANNELS=['counter','pickup','delivery'];private const EPSILON=.0005;
    public function supportsChannel(string$c):bool{return in_array(strtolower(trim($c)),self::QR_CHANNELS,true);}
    public function qrPayload(string$t):string{return \app_absolute_url('?route=pickup&token='.rawurlencode($this->normalizeToken($t)));}
    public function qrDataUri(string$t,int$size=320):string{$size=max(180,min(700,$size));$qr=new QrCode(data:$this->qrPayload($t),encoding:new Encoding('ISO-8859-1'),errorCorrectionLevel:ErrorCorrectionLevel::Medium,size:$size,margin:12,roundBlockSizeMode:RoundBlockSizeMode::Margin);return(new SvgWriter())->write($qr)->getDataUri();}
    public function normalizeToken(string$raw):string{$raw=trim($raw);if($raw==='')throw new RuntimeException('QR do pedido vazio.');if(preg_match('/^[a-f0-9]{40}$/i',$raw))return strtolower($raw);if(preg_match('/EVENTMENU:ORDER:([a-f0-9]{40})/i',$raw,$m))return strtolower($m[1]);$query=(string)(parse_url($raw,PHP_URL_QUERY)??'');if($query!==''){parse_str($query,$params);foreach(['token','t','order']as$k){$v=trim((string)($params[$k]??''));if(preg_match('/^[a-f0-9]{40}$/i',$v))return strtolower($v);}}if(preg_match('/(?:token|t|order)=([a-f0-9]{40})/i',$raw,$m))return strtolower($m[1]);throw new RuntimeException('QR de pedido inválido.');}
    public function detailsByToken(string$raw):array{$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa não selecionada.');$pdo=Database::connection();$o=$this->fetchOrderByToken($pdo,$tenantId,$this->normalizeToken($raw),false);$this->assertCanView($o);$this->assertUnitContext($o);return$this->composeDetails($pdo,$o);}
    public function search(string$query,int$limit=20):array{$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa não selecionada.');if(!Auth::can('orders.fulfill')&&!Auth::can('orders.view'))throw new RuntimeException('Sem permissão para localizar pedidos.');$q=trim($query);if($q==='')return[];$unitId=(new OperatingUnitService())->currentId();$pdo=Database::connection();$where='o.tenant_id=? AND o.channel IN ("counter","pickup","delivery")';$args=[$tenantId];if($unitId){$where.=' AND o.unit_id=?';$args[]=$unitId;}if(ctype_digit(ltrim($q,'#'))){$where.=' AND o.id=?';$args[]=(int)ltrim($q,'#');}else{$where.=' AND (c.name LIKE ? OR c.phone LIKE ? OR o.public_token LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}$s=$pdo->prepare('SELECT o.id,o.public_token,o.channel,o.status,o.payment_status,o.total_cents,o.created_at,c.name customer_name,c.phone customer_phone,ou.name unit_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN operating_units ou ON ou.id=o.unit_id WHERE '.$where.' ORDER BY o.id DESC LIMIT '.max(1,min(50,$limit)));$s->execute($args);return$s->fetchAll();}
    public function publicProgress(int$tenantId,int$orderId):array{if($tenantId<1||$orderId<1)return$this->emptyProgress();return$this->progressFromItems($this->fetchItems(Database::connection(),$tenantId,$orderId));}

    public function fulfill(string$raw,array$quantities,string$batchKey='',string$notes=''):array
    {
        $tenantId=Auth::tenantId();$userId=Auth::id();if(!$tenantId||!$userId)throw new RuntimeException('Sessão inválida.');$token=$this->normalizeToken($raw);$batchKey=preg_replace('/[^A-Za-z0-9:_-]/','',trim($batchKey))?:bin2hex(random_bytes(16));$batchKey=mb_substr($batchKey,0,80);$notes=mb_substr(trim($notes),0,500);$requested=[];foreach($quantities as$itemId=>$rawQty){$id=(int)$itemId;$qty=round((float)str_replace(',','.',(string)$rawQty),3);if($id>0&&is_finite($qty)&&$qty>self::EPSILON)$requested[$id]=$qty;}if(!$requested)throw new RuntimeException('Informe pelo menos um item retirado.');
        return Database::transaction(function(PDO$pdo)use($tenantId,$userId,$token,$batchKey,$notes,$requested):array{$order=$this->fetchOrderByToken($pdo,$tenantId,$token,true);$this->assertCanFulfill($order);$this->assertUnitContext($order);if(!$this->supportsChannel((string)$order['channel']))throw new RuntimeException('Pedido de mesa/comanda não usa retirada por QR.');if((string)$order['status']==='cancelled')throw new RuntimeException('Pedido cancelado não pode ter itens retirados.');if((int)$order['total_cents']>0&&(string)$order['payment_status']!=='paid')throw new RuntimeException('Pagamento ainda não confirmado. Receba o pedido antes de liberar produtos.');$currentStatus=(string)$order['status'];if($currentStatus==='pending'){$pdo->prepare('UPDATE orders SET status="confirmed" WHERE id=? AND tenant_id=?')->execute([(int)$order['id'],$tenantId]);$pdo->prepare('UPDATE stock_reservations SET expires_at=NULL WHERE tenant_id=? AND order_id=? AND status="reserved"')->execute([$tenantId,(int)$order['id']]);(new ProductionService())->ensureOrderJobs($pdo,$tenantId,(int)$order['id'],$userId);(new OrderHistoryService())->record($pdo,$tenantId,(int)$order['id'],'pending','confirmed','fulfillment','Pedido aceito ao iniciar retirada por QR.',$userId);$currentStatus='confirmed';$order['status']='confirmed';}$before=$this->composeDetails($pdo,$order);if((string)$order['status']==='completed'){if(($before['progress']['status']??'')==='fulfilled')return$before;throw new RuntimeException('Pedido encerrado possui itens pendentes. Solicite revisão de um gerente.');}$dup=$pdo->prepare('SELECT id FROM order_item_fulfillments WHERE tenant_id=? AND batch_key=? LIMIT 1');$dup->execute([$tenantId,$batchKey]);if($dup->fetchColumn())return$this->composeDetails($pdo,$order);$map=[];foreach($before['items']as$item)$map[(int)$item['id']]=$item;$ins=$pdo->prepare('INSERT INTO order_item_fulfillments (tenant_id,order_id,order_item_id,quantity,fulfilled_by,source,batch_key,notes) VALUES (?,?,?,?,?,"qr",?,?)');foreach($requested as$itemId=>$qty){$item=$map[$itemId]??null;if(!$item)throw new RuntimeException('Um item selecionado não pertence a este pedido.');$available=(float)$item['available_quantity'];if($qty-$available>self::EPSILON){$why=(float)$item['production_ready_quantity']+self::EPSILON<(float)$item['ordered_quantity']?'Ainda não está liberado pela produção':'Quantidade maior que o saldo disponível';throw new RuntimeException($why.' para '.$item['name_snapshot'].'. Disponível agora: '.$this->formatQty($available).'.');}$ins->execute([$tenantId,(int)$order['id'],$itemId,$qty,$userId,$batchKey,$notes?:null]);}$details=$this->composeDetails($pdo,$order);if(($details['progress']['status']??'')==='fulfilled'&&in_array((string)$order['channel'],['counter','pickup'],true)&&$currentStatus!=='completed'){$pdo->prepare('UPDATE orders SET status="completed" WHERE id=? AND tenant_id=?')->execute([(int)$order['id'],$tenantId]);(new OrderHistoryService())->record($pdo,$tenantId,(int)$order['id'],$currentStatus,'completed','fulfillment','Todos os itens foram entregues por retirada QR.',$userId);$details['order']['status']='completed';}Auth::audit('order.fulfillment','order',(string)$order['id'],['batch_key'=>$batchKey,'items'=>$requested,'fulfillment_status'=>$details['progress']['status']??'pending','unit_id'=>$order['unit_id']??null]);return$details;});
    }

    public function correct(int$fulfillmentId,float$quantity,string$reason):array
    {
        if(!Auth::can('orders.fulfillment_correct'))throw new RuntimeException('Somente gerente ou administrador autorizado pode corrigir uma retirada.');$tenantId=Auth::tenantId();$userId=Auth::id();if(!$tenantId||!$userId)throw new RuntimeException('Sessão inválida.');$quantity=round($quantity,3);if(!is_finite($quantity)||$quantity<=self::EPSILON)throw new RuntimeException('Quantidade de correção inválida.');$reason=mb_substr(trim($reason),0,500);if($reason==='')throw new RuntimeException('Informe o motivo da correção.');
        return Database::transaction(function(PDO$pdo)use($tenantId,$userId,$fulfillmentId,$quantity,$reason):array{$s=$pdo->prepare(Database::portableSql($pdo,'SELECT f.*,o.public_token,o.status order_status,o.unit_id,o.channel,o.tenant_id FROM order_item_fulfillments f JOIN orders o ON o.id=f.order_id AND o.tenant_id=f.tenant_id WHERE f.id=? AND f.tenant_id=? FOR UPDATE'));$s->execute([$fulfillmentId,$tenantId]);$f=$s->fetch();if(!$f)throw new RuntimeException('Registro de retirada não encontrado.');$this->assertUnitContext($f);$c=$pdo->prepare('SELECT COALESCE(SUM(quantity),0) FROM order_item_fulfillment_corrections WHERE tenant_id=? AND fulfillment_id=?');$c->execute([$tenantId,$fulfillmentId]);$corrected=(float)$c->fetchColumn();$available=max(0,(float)$f['quantity']-$corrected);if($quantity-$available>self::EPSILON)throw new RuntimeException('A correção excede a quantidade ainda válida deste registro ('.$this->formatQty($available).').');$pdo->prepare('INSERT INTO order_item_fulfillment_corrections (tenant_id,order_id,order_item_id,fulfillment_id,quantity,reason,requested_by,approved_by) VALUES (?,?,?,?,?,?,?,?)')->execute([$tenantId,$f['order_id'],$f['order_item_id'],$fulfillmentId,$quantity,$reason,$f['fulfilled_by']?:null,$userId]);$order=$this->fetchOrderByToken($pdo,$tenantId,(string)$f['public_token'],true);$details=$this->composeDetails($pdo,$order);if((string)$f['order_status']==='completed'&&($details['progress']['status']??'')!=='fulfilled'){$next=$this->productionStateForReopen($pdo,$tenantId,(int)$f['order_id']);$pdo->prepare('UPDATE orders SET status=? WHERE id=? AND tenant_id=?')->execute([$next,$f['order_id'],$tenantId]);(new OrderHistoryService())->record($pdo,$tenantId,(int)$f['order_id'],'completed',$next,'fulfillment_correction','Retirada corrigida: '.$reason,$userId);$details['order']['status']=$next;}Auth::audit('order.fulfillment_corrected','order',(string)$f['order_id'],['fulfillment_id'=>$fulfillmentId,'quantity'=>$quantity,'reason'=>$reason,'unit_id'=>$f['unit_id']??null]);return$details;});
    }

    private function fetchOrderByToken(PDO$pdo,int$tenantId,string$token,bool$lock):array{$sql='SELECT o.*,c.name customer_name,c.phone customer_phone,u.name delivery_name,rt.name table_name,ou.name unit_name FROM orders o LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN users u ON u.id=o.assigned_delivery_user_id LEFT JOIN restaurant_tables rt ON rt.id=o.table_id LEFT JOIN operating_units ou ON ou.id=o.unit_id WHERE o.tenant_id=? AND o.public_token=? LIMIT 1';if($lock)$sql=Database::portableSql($pdo,str_replace(' LIMIT 1',' LIMIT 1 FOR UPDATE',$sql));$s=$pdo->prepare($sql);$s->execute([$tenantId,$token]);$o=$s->fetch();if(!$o)throw new RuntimeException('Pedido não encontrado para este QR.');return$o;}
    private function fetchItems(PDO$pdo,int$tenantId,int$orderId):array{$s=$pdo->prepare('SELECT oi.* FROM order_items oi WHERE oi.order_id=? ORDER BY oi.id');$s->execute([$orderId]);$items=$s->fetchAll();if(!$items)return[];$map=[];foreach($items as$i)$map[(int)$i['id']]=['f'=>0.,'c'=>0.,'mods'=>[],'all'=>0,'active'=>0,'ready'=>0];$f=$pdo->prepare('SELECT order_item_id,SUM(quantity) qty FROM order_item_fulfillments WHERE tenant_id=? AND order_id=? GROUP BY order_item_id');$f->execute([$tenantId,$orderId]);foreach($f->fetchAll()as$r)if(isset($map[(int)$r['order_item_id']]))$map[(int)$r['order_item_id']]['f']=(float)$r['qty'];try{$c=$pdo->prepare('SELECT order_item_id,SUM(quantity) qty FROM order_item_fulfillment_corrections WHERE tenant_id=? AND order_id=? GROUP BY order_item_id');$c->execute([$tenantId,$orderId]);foreach($c->fetchAll()as$r)if(isset($map[(int)$r['order_item_id']]))$map[(int)$r['order_item_id']]['c']=(float)$r['qty'];}catch(\Throwable){}try{$m=$pdo->prepare('SELECT order_item_id,group_name_snapshot,option_name_snapshot,quantity FROM order_item_modifiers WHERE tenant_id=? AND order_id=? ORDER BY id');$m->execute([$tenantId,$orderId]);foreach($m->fetchAll()as$r)if(isset($map[(int)$r['order_item_id']]))$map[(int)$r['order_item_id']]['mods'][]=$r;}catch(\Throwable){}try{$j=$pdo->prepare('SELECT pj.status,COALESCE(pj.order_item_id,m.order_item_id) item_id FROM production_jobs pj LEFT JOIN order_item_modifiers m ON m.id=pj.order_item_modifier_id WHERE pj.tenant_id=? AND pj.order_id=?');$j->execute([$tenantId,$orderId]);foreach($j->fetchAll()as$r){$id=(int)$r['item_id'];if(!$id||!isset($map[$id]))continue;$map[$id]['all']++;if($r['status']!=='cancelled'){$map[$id]['active']++;if(in_array((string)$r['status'],['ready','expedited','delivered'],true))$map[$id]['ready']++;}}}catch(\Throwable){}foreach($items as&$item){$meta=$map[(int)$item['id']];$ordered=(float)$item['quantity'];$fulfilled=min($ordered,max(0,$meta['f']-$meta['c']));$hasJobs=$meta['all']>0;$prodReady=!$hasJobs||($meta['active']>0&&$meta['ready']>=$meta['active']);$readyQty=$prodReady?$ordered:0.;$item['ordered_quantity']=$ordered;$item['fulfilled_quantity']=$fulfilled;$item['remaining_quantity']=max(0,$ordered-$fulfilled);$item['production_ready_quantity']=$readyQty;$item['available_quantity']=max(0,min($item['remaining_quantity'],$readyQty-$fulfilled));$item['production_status']=!$hasJobs?'not_required':($prodReady?'ready':'waiting');$item['production_jobs_total']=$meta['active'];$item['production_jobs_ready']=$meta['ready'];$item['modifiers']=$meta['mods'];}unset($item);return$items;}
    private function composeDetails(PDO$pdo,array$order):array{$items=$this->fetchItems($pdo,(int)$order['tenant_id'],(int)$order['id']);$h=$pdo->prepare('SELECT f.id,f.quantity,f.source,f.notes,f.created_at,oi.name_snapshot,u.name fulfilled_by_name,COALESCE((SELECT SUM(c.quantity) FROM order_item_fulfillment_corrections c WHERE c.fulfillment_id=f.id),0) corrected_quantity FROM order_item_fulfillments f JOIN order_items oi ON oi.id=f.order_item_id LEFT JOIN users u ON u.id=f.fulfilled_by WHERE f.tenant_id=? AND f.order_id=? ORDER BY f.id DESC LIMIT 100');$h->execute([(int)$order['tenant_id'],(int)$order['id']]);$corrections=[];try{$c=$pdo->prepare('SELECT c.*,oi.name_snapshot,ua.name approved_by_name,ur.name requested_by_name FROM order_item_fulfillment_corrections c JOIN order_items oi ON oi.id=c.order_item_id JOIN users ua ON ua.id=c.approved_by LEFT JOIN users ur ON ur.id=c.requested_by WHERE c.tenant_id=? AND c.order_id=? ORDER BY c.id DESC LIMIT 100');$c->execute([(int)$order['tenant_id'],(int)$order['id']]);$corrections=$c->fetchAll();}catch(\Throwable){}return['order'=>$order,'items'=>$items,'progress'=>$this->progressFromItems($items),'history'=>$h->fetchAll(),'corrections'=>$corrections,'qr_payload'=>$this->qrPayload((string)$order['public_token'])];}
    private function progressFromItems(array$items):array{$ordered=$fulfilled=$ready=$available=0.;foreach($items as$i){$ordered+=(float)($i['ordered_quantity']??$i['quantity']??0);$fulfilled+=(float)($i['fulfilled_quantity']??0);$ready+=(float)($i['production_ready_quantity']??0);$available+=(float)($i['available_quantity']??0);}$remaining=max(0,$ordered-$fulfilled);$status=$fulfilled<=self::EPSILON?'pending':($remaining<=self::EPSILON?'fulfilled':'partial');return['status'=>$status,'ordered_quantity'=>round($ordered,3),'fulfilled_quantity'=>round($fulfilled,3),'remaining_quantity'=>round($remaining,3),'production_ready_quantity'=>round($ready,3),'available_quantity'=>round($available,3)];}
    private function emptyProgress():array{return['status'=>'pending','ordered_quantity'=>0.,'fulfilled_quantity'=>0.,'remaining_quantity'=>0.,'production_ready_quantity'=>0.,'available_quantity'=>0.];}
    private function productionStateForReopen(PDO$pdo,int$tenantId,int$orderId):string{$s=$pdo->prepare('SELECT status,COUNT(*) qty FROM production_jobs WHERE tenant_id=? AND order_id=? AND status<>"cancelled" GROUP BY status');$s->execute([$tenantId,$orderId]);$rows=$s->fetchAll();if(!$rows)return'confirmed';$active=$ready=$preparing=0;foreach($rows as$r){$q=(int)$r['qty'];$active+=$q;if(in_array($r['status'],['ready','expedited','delivered'],true))$ready+=$q;if($r['status']==='preparing')$preparing+=$q;}return$active>0&&$ready>=$active?'ready':($preparing>0?'preparing':'confirmed');}
    private function assertCanView(array$o):void{$allowed=Auth::can('orders.view')||Auth::can('orders.manage')||Auth::can('orders.dispatch')||Auth::can('orders.fulfill');if(!$allowed&&Auth::can('orders.delivery')&&(string)$o['channel']==='delivery'&&(int)($o['assigned_delivery_user_id']??0)===(int)Auth::id())$allowed=true;if(!$allowed)throw new RuntimeException('Sua função não pode visualizar esta retirada.');}
    private function assertCanFulfill(array$o):void{if(Auth::can('orders.fulfill'))return;if(Auth::can('orders.delivery')&&(string)$o['channel']==='delivery'&&(int)($o['assigned_delivery_user_id']??0)===(int)Auth::id())return;throw new RuntimeException('Sua função não pode entregar itens deste pedido.');}
    private function assertUnitContext(array$o):void{$orderUnit=(int)($o['unit_id']??0);if($orderUnit<1)return;$current=(new OperatingUnitService())->currentId();if($current&&$current!==$orderUnit&&!Auth::isSuperAdmin())throw new RuntimeException('Este pedido pertence a outra unidade. Troque a unidade de operação antes de continuar.');}
    private function formatQty(float$q):string{if(abs($q-round($q))<self::EPSILON)return(string)(int)round($q);return rtrim(rtrim(number_format($q,3,',','.'),'0'),',');}
}
